function throttle(fn, limitMs) {
  let zablokowane = false;
  return (...args) => {
    if (zablokowane) return;
    fn(...args);
    zablokowane = true;
    setTimeout(() => { zablokowane = false; }, limitMs);
  };
}
let licznik = 0;
const throttled = throttle(() => { licznik++; }, 1000);
throttled();
throttled();
throttled();
console.log(licznik);
// 1 - tylko pierwsze wywolanie przeszlo, pozostale byly zablokowane

function debounce(fn, opoznienieMs) {
  let idTimeoutu;
  return (...args) => {
    clearTimeout(idTimeoutu);
    idTimeoutu = setTimeout(() => fn(...args), opoznienieMs);
  };
}
let licznik = 0;
const debounced = debounce(() => licznik++, 200);
debounced();
debounced();
debounced();
setTimeout(() => console.log(licznik), 300);
