class MiniEventTarget {
  constructor() { this._h = {}; }
  addEventListener(typ, fn, opcje = {}) {
    const wrapper = opcje.once ? (...a) => { this.removeEventListener(typ, wrapper); fn(...a); } : fn;
    (this._h[typ] = this._h[typ] || []).push(wrapper);
  }
  removeEventListener(typ, fn) {
    if (this._h[typ]) this._h[typ] = this._h[typ].filter((f) => f !== fn);
  }
  dispatch(typ) { (this._h[typ] || []).slice().forEach((fn) => fn()); }
}
const window = new MiniEventTarget();
let licznik = 0;
window.addEventListener("load", () => licznik++, { once: true });
window.dispatch("load");
window.dispatch("load");
console.log(licznik);
// 1

