function throttleZOstatnim(fn, limitMs) {
  let zablokowane = false;
  let oczekujaceArgumenty = null;
  function odblokuj() {
    if (oczekujaceArgumenty) {
      fn(...oczekujaceArgumenty);
      oczekujaceArgumenty = null;
      setTimeout(odblokuj, limitMs);
    } else {
      zablokowane = false;
    }
  }
  return (...args) => {
    if (zablokowane) { oczekujaceArgumenty = args; return; }
    fn(...args);
    zablokowane = true;
    setTimeout(odblokuj, limitMs);
  };
}
const wyniki = [];
const throttled = throttleZOstatnim((x) => wyniki.push(x), 100);
