console.log(opisRozmiaruOkna({ innerWidth: 900 }));
console.log(opisRozmiaruOkna({ innerWidth: 1440 }));
// "mobile" "tablet" "desktop"

function obliczSzerokoscPaskaPrzegladarki(window) {
  return window.outerWidth - window.innerWidth;
}
console.log(obliczSzerokoscPaskaPrzegladarki({ outerWidth: 1300, innerWidth: 1280 }));
// 20

